html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
<div class="ap">
{{ ap.header(c, "DAILY MANPOWER SHEET", "كشف العمالة اليومي", [
    ["Entry No.", doc.name],
    ["Date", ap.date(doc.posting_date)],
    ["Status", "Draft" if doc.docstatus == 0 else ("Cancelled" if doc.docstatus == 2 else "Submitted")]
]) }}
{{ ap.two_boxes(ap.info_box("Project", [
    ["Project", doc.project],
    ["Project Name", doc.get("project_name")],
    ["Task", doc.get("task")],
    ["Budget Line", doc.get("item_group")]
]), ap.info_box("Summary", [
    ["Workers", doc.get("total_workers")],
    ["Hours / OT Hours", (ap.num(doc.get("total_hours")) ~ " / " ~ ap.num(doc.get("total_ot_hours")))],
    ["Own Staff Cost", ap.money(doc.get("own_staff_cost"), doc)],
    ["Outsourced Cost", ap.money(doc.get("outsourced_cost"), doc)]
])) }}
<table class="items">
  <thead><tr>
    <th style="width:5%">#</th><th>Worker / Crew</th><th style="width:10%">Type</th><th style="width:17%">Agency</th><th style="width:11%">Trade</th>
    <th class="right" style="width:7%">Workers</th><th class="right" style="width:6%">Hrs</th><th class="right" style="width:6%">OT</th>
    <th class="right" style="width:9%">Rate / OT</th><th class="right" style="width:11%">Amount ({{ doc.currency }})</th>
  </tr></thead>
  <tbody>
  {%- for d in doc.get("details") %}
  <tr><td>{{ loop.index }}</td><td><b>{{ d.employee_name or ("Crew" if d.no_of_workers and d.no_of_workers > 1 else "Worker") }}</b>{% if d.employee %}<div class="muted">{{ d.employee }}</div>{% endif %}</td>
    <td>{{ d.worker_type }}</td><td>{{ d.supplier or "" }}</td><td>{{ d.designation or "" }}</td>
    <td class="right">{{ d.no_of_workers }}</td><td class="right">{{ ap.num(d.working_hours) }}</td><td class="right">{{ ap.num(d.ot_hours) }}</td>
    <td class="right nowrap">{{ ap.num(d.hourly_rate) }} / {{ ap.num(d.ot_hourly_rate) }}</td><td class="right"><b>{{ ap.amt(d.amount) }}</b></td></tr>
  {%- endfor %}
  <tr class="grp"><td></td><td colspan="4" class="right">Total</td><td class="right">{{ doc.get("total_workers") }}</td><td class="right">{{ ap.num(doc.get("total_hours")) }}</td><td class="right">{{ ap.num(doc.get("total_ot_hours")) }}</td><td></td><td class="right">{{ ap.amt(doc.get("total_cost")) }}</td></tr>
  </tbody>
</table>
{{ ap.section("Remarks", doc.get("remarks")) }}
{{ ap.signatures(c, ["Site Supervisor", "Project Manager", "Agency Representative"], 9) }}
{{ ap.footer(c) }}
</div>
